schema_sql:
CREATE TABLE access_logs (
  log_id    INTEGER,
  user_id   INTEGER,
  logged_at DATE,
  status    INTEGER
);
CREATE TABLE month_master (
  ym         VARCHAR,
  start_date DATE,
  end_date   DATE
);

CREATE TABLE customers (
  customer_id INTEGER,
  name        VARCHAR,
  city        VARCHAR
);
CREATE TABLE orders (
  order_id    INTEGER,
  customer_id INTEGER,
  order_date  DATE,
  amount      INTEGER
);
